create table categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, image_url text, created_at timestamptz default now());
create table brands (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, logo_url text);
create table products (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, sku text unique not null, description text, short_description text, price numeric(12,2), category_id uuid references categories(id), brand_id uuid references brands(id), stock integer default 0, warranty_months integer default 0, featured boolean default false, active boolean default true, created_at timestamptz default now());
create table product_images (id uuid primary key default gen_random_uuid(), product_id uuid references products(id) on delete cascade, url text not null, alt text, position integer default 0);
create table product_specs (id uuid primary key default gen_random_uuid(), product_id uuid references products(id) on delete cascade, label text not null, value text not null, unit text, position integer default 0);
create table orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, customer_name text not null, email text, phone text, address text, department text, municipality text, payment_method text, status text default 'pending', subtotal numeric(12,2), shipping numeric(12,2), total numeric(12,2), created_at timestamptz default now());
create table order_items (id uuid primary key default gen_random_uuid(), order_id uuid references orders(id) on delete cascade, product_id uuid references products(id), product_name text not null, quantity integer not null, unit_price numeric(12,2), subtotal numeric(12,2));
